  "what-is-this-thing-called-love": "X:1\nT:What Is This Thing Called Love?\nC:Cole Porter, 1929 (Wake Up and Dream)\nM:4/4\nL:1/16\nQ:1/4=92\nK:Am clef=treble\n\"A7\"g4 | \"A7\"g4 e4 e8- | \"A7\"e8 g8 | \"Dm\"f16- |\n\"Dm\"f8 z4 g4 | \"E7\"g4 e4 e8- | \"E7\"e8 \"E\"c8 | \"A\"^c8- \"A7\"c8- |\n\"F#7\"^c8 \"A\"z4 \"A7\"g4 | \"A7\"g4 e4 e8- | \"A#dim\"e4 g4 \"F#\"a6 ^f2 | \"Dm\"f16- |\n\"Dm\"f8 z4 g4 | \"E7\"g4 e4 e8- | \"E7\"e8 \"E\"c8 | \"A\"^c8- \"A7\"c8 |\n\"Dm\"z8 \"A\"z4 a4 | \"Am\"c'4 \"D7\"a4 a8- | \"D7\"a4 c'4 (3c'4 d'4 c'4 | \"G\"b16- |\n\"G\"b8 \"F\"z4 c'4 | \"F\"c'4 a4 a8- | \"Dm\"a4 f4 (3a4 g4 f4 | \"E\"e8- \"Am\"e8 |\n\"E7\"z4 g4 e4 e4 | \"A7\"g4 e4 e8- | \"A#dim\"e4 g4 a4 g4 | \"Dm\"f16- |\n\"Dm\"f8 z4 g4 | \"E7\"g4 e4 e8- | \"E\"e8 g8 | \"A\"a16- |\n\"Dm\"a8- \"A\"Ha8 |]\n",
  "you-took-advantage-of-me": "X:1\nT:You Took Advantage of Me\nC:Richard Rodgers, 1928 (Present Arms)\nM:4/4\nL:1/16\nQ:1/4=130\nK:C clef=treble\n\"C6\"g2g2 c2B2 \"C#dim\"_B2 a6 | \"Dm7\"a4 g2g2- \"G7\"g8 | \"Em\"g2g2 a2g2 \"Ebdim\"^f2 c'6 | \"Dm7\"c'4 b2b2- \"G7\"b4 d'4 |\n\"Gm7\"d'4 c'2c'2- \"C7\"c'4 g4 | \"F6\"g4 f2f2- \"Bb7\"f4 c2d2 | \"Em\"e4 \"A7\"e4 \"Dm7\"d2c2 \"G7\"d4 | \"C6\"c16 |\n\"C6\"g2g2 c2B2 \"C#dim\"_B2 a6 | \"Dm7\"a4 g2g2- \"G7\"g8 | \"Em\"g2g2 a2g2 \"Ebdim\"^f2 c'6 | \"Dm7\"c'4 b2b2- \"G7\"b4 d'4 |\n\"Gm7\"d'4 c'2c'2- \"C7\"c'4 g4 | \"F6\"g4 f2f2- \"Bb7\"f4 c2d2 | \"Em\"e4 \"A7\"e4 \"Dm7\"d2c2 \"G7\"d4 | \"C6\"c16 |\n\"F#m7b5\"c'2c'2 d'2c'2 \"B7\"b2 b4 a2 | \"E7\"^g4 _b2a2- \"A7\"a6 =g2 | \"D7\"^f4 _a2g2- \"G7\"g4 d4 | \"C6\"e8- e4 z2 b2 |\n\"F#m7b5\"c'2c'2 d'2c'2 \"B7\"b2 b4 a2 | \"E7\"^g4 _b2a2- \"A7\"a6 =g2 | \"D7\"^f4 _a2g2- \"G7\"g4 d4 | \"Em\"g4- \"A7\"g4- \"Dm7\"g4- \"G7\"g4 |\n\"C6\"g2g2 c2B2 \"C#dim\"_B2 a6 | \"Dm7\"a4 g2g2- \"G7\"g8 | \"Em\"g2g2 a2g2 \"Ebdim\"^f2 c'6 | \"Dm7\"c'4 b2b2- \"G7\"b4 d'4 |\n\"Gm7\"d'4 c'2c'2- \"C7\"c'4 g4 | \"F6\"g4 f2f2- \"Bb7\"f4 c2d2 | \"Em\"e4 \"A7\"e4 \"Dm7\"d2c2 \"G7\"d4 | \"C6\"Hc16 |]\n"
